Unit Test Code:
#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_delete_bt_leaf_node_not_found(void) {
    // Build a small tree: root with a left child
    int values[] = {10, 5};
    node* root = helper_build_tree(values, 2);

    // Attempt to delete a value that does NOT exist in the tree (e.g., 99)
    // This will cause the search loop to exit without finding the element (temp == NULL after loop)
    // Path conditions:
    // 1. *root != NULL (tree not empty)
    // 2. Loop runs but never finds element, exits with temp == NULL
    // 3. temp == NULL branch taken -> return without changes
    int element_to_delete = 99;

    // Capture tree state before deletion
    stdout_capture_t* cap_before = capture_stdout_start();
    inorder_display(root);
    char* inorder_before = capture_stdout_stop(cap_before);
    // We'll just store the string for comparison; actual assertion via helper later.

    // Perform deletion (should do nothing)
    delete_bt(&root, element_to_delete);

    // Assert that tree is unchanged
    // Verify that element 99 is still not present
    helper_assert_search_result(root, element_to_delete, 0);
    // Verify that original elements are still present
    helper_assert_search_result(root, 10, 1);
    helper_assert_search_result(root, 5, 1);

    // Cleanup
    free(inorder_before);
    helper_free_tree(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_delete_bt_leaf_node_not_found);
    return UNITY_END();
}

